132	func (s *Store) DeleteAttachment(ctx context.Context, delete *DeleteAttachment) error {
133		attachment, err := s.GetAttachment(ctx, &FindAttachment{ID: &delete.ID})
134		if err != nil {
135			return errors.Wrap(err, "failed to get attachment")
136		}
137		if attachment == nil {
138			return errors.New("attachment not found")
139		}
140	
141		if err := s.DeleteAttachmentStorage(ctx, attachment); err != nil {
142			if attachment.StorageType == storepb.AttachmentStorageType_LOCAL {
143				return errors.Wrap(err, "failed to delete local file")
144			}
145			slog.Warn("Failed to delete attachment storage", slog.Any("err", err))
146		}
147	
148		return s.driver.DeleteAttachment(ctx, delete)
149	}
